<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import { useRoute } from 'vue-router'
import * as echarts from 'echarts/core'
import { LineChart } from 'echarts/charts'
import { GridComponent, TooltipComponent, LegendComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { api } from '../../api/client'
import type { Dashboard, Page, Rank } from '../../api/types'
import { useSession } from '../../app/session'
import RequireLogin from '../../components/RequireLogin.vue'
import ErrorBanner from '../../components/ErrorBanner.vue'
echarts.use([LineChart, GridComponent, TooltipComponent, LegendComponent, CanvasRenderer])
const route = useRoute(); const session = useSession(); const days = ref(7); const scope = ref(route.path.startsWith('/admin') ? 'platform' : 'me'); const result = ref<Dashboard | null>(null); const ranking = ref<Rank[]>([]); const error = ref(''); const element = ref<HTMLDivElement>(); let chart: echarts.ECharts | undefined; let observer: ResizeObserver | undefined
const names: Record<string, string> = { VIEW: '有效浏览', DAU: '活跃用户', LIKE_ADD: '新增点赞', LIKE_REMOVE: '取消点赞', COMMENT_ADD: '新增评论', FOLLOW_ADD: '新增关注', FOLLOW_REMOVE: '取消关注', NOTE_PUBLISHED: '发布次数', REVIEW_PENDING: '待审核量', REVIEW_DURATION_MS: '平均处理时长(ms)', REPORT_ACCEPTED: '受理举报', REPORT_CLOSED: '已结案举报', PRACTICE_CREATED: '新建实践', PRACTICE_DONE: '已完成实践' }
const totals = computed(() => { const sums: Record<string, number> = {}; for (const p of result.value?.points ?? []) sums[p.metric] = (sums[p.metric] ?? 0) + Number(p.value); return Object.entries(sums) })
function draw() { if (!element.value || !result.value?.points.length) { chart?.dispose(); chart = undefined; return } chart?.dispose(); chart = echarts.init(element.value); const days = [...new Set(result.value.points.map(p => p.day))].sort(); const metrics = [...new Set(result.value.points.map(p => p.metric))]; chart.setOption({ color: ['#df3b51', '#4a8270', '#7f6c9f', '#b88743', '#447e9d'], tooltip: { trigger: 'axis' }, legend: { bottom: 0, type: 'scroll' }, grid: { left: 45, right: 20, top: 20, bottom: 60 }, xAxis: { type: 'category', data: days.map(x => x.slice(5)), boundaryGap: false }, yAxis: { type: 'value', minInterval: 1 }, series: metrics.map(metric => ({ name: names[metric] ?? metric, type: 'line', smooth: false, symbolSize: 5, data: days.map(day => Number(result.value?.points.find(p => p.day === day && p.metric === metric)?.value ?? 0)) })) }); observer?.disconnect(); observer = new ResizeObserver(() => chart?.resize()); observer.observe(element.value) }
async function load() { if (!session.user) return; error.value = ''; try { const base = scope.value === 'me' ? '/statistics/me' : '/admin/statistics/' + scope.value; result.value = await api<Dashboard>(base + '?days=' + days.value); if (scope.value !== 'governance') ranking.value = (await api<Page<Rank>>(scope.value === 'me' ? '/statistics/me/ranking' : '/admin/statistics/ranking')).items; else ranking.value = []; await nextTick(); draw() } catch (e) { error.value = e instanceof Error ? e.message : '加载失败' } }
watch([days, scope], load); onMounted(load); onUnmounted(() => { observer?.disconnect(); chart?.dispose() })
</script>
<template><RequireLogin><header class="page-heading"><div><h1>{{ scope === 'me' ? '创作者中心' : scope === 'governance' ? '治理与实践统计' : '平台运营统计' }}</h1><p>每一次真实的分享与互动，都有迹可循。</p></div><select v-model="days" aria-label="统计时间范围" class="button"><option :value="7">最近7日</option><option :value="30">最近30日</option></select></header><nav class="tabs"><button :class="{ active: scope === 'me' }" @click="scope = 'me'">我的创作</button><button v-if="session.has('ADMIN')" :class="{ active: scope === 'platform' }" @click="scope = 'platform'">平台汇总</button><button v-if="session.has('ADMIN') || session.has('REVIEWER')" :class="{ active: scope === 'governance' }" @click="scope = 'governance'">治理统计</button></nav><ErrorBanner :message="error" :retry="load" /><template v-if="result"><div class="dashboard-grid"><div v-for="[metric, value] in totals" :key="metric" class="metric-panel"><h3>{{ names[metric] ?? metric }}</h3><strong>{{ value.toLocaleString('zh-CN', { maximumFractionDigits: 1 }) }}</strong></div></div><div v-if="result.points.length" ref="element" class="chart" role="img" aria-label="选定时间范围的每日业务指标趋势" /><div v-else class="empty-state"><h2>还没有可展示的数据</h2><p>完成发布、浏览或互动后，异步统计将逐步更新。</p></div><p class="hint">时间口径：北京时间 · 汇总水位 {{ new Date(result.calculatedAt).toLocaleString('zh-CN') }} · 点赞/收藏为当前有效关系，日趋势为动作次数。平均处理时长和当日活跃量请按日查看，不将跨日累加当作整体平均或去重人数。</p><div v-if="ranking.length" class="section"><h2>内容表现</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>笔记</th><th>指标</th><th>数值</th></tr></thead><tbody><tr v-for="row in ranking" :key="row.subjectId"><td><RouterLink :to="'/notes/' + row.subjectId">{{ row.label }}</RouterLink></td><td>当前有效点赞</td><td>{{ row.value }}</td></tr></tbody></table></div></div></template></RequireLogin></template>
